import xml.etree.ElementTree as ET, re, sys

def text_of(el):
    out=[]
    if el.text: out.append(el.text)
    for c in el:
        if c.tag in ('BRK','BRL'):
            out.append(' ')
        elif c.tag in ('NPR','NTE'):
            pass
        else:
            out.append(text_of(c))
        if c.tail: out.append(c.tail)
    return ''.join(out)

BLOCK={'SCN','STL','DTE','HL1','HL2','HL3','HL4','TTL','SPT','OLI','ITM','TAI','NTE','NPR','RTL','OLG','LST','SUB','TXT'}

def walk(el, out, skip=False):
    for c in el:
        if c.tag in ('NPR','NTE'):
            continue
        if c.tag in BLOCK:
            t=re.sub(r'\s+',' ',text_of(c)).strip()
            if t: out.append((c.tag,t))
            continue
        walk(c,out)

root=ET.parse(sys.argv[1]).getroot()
out=[]
walk(root,out)
for tag,t in out:
    print(f'[{tag}] {t}')
EOF
